import Openai from "openai";

const client = new Openai({
  apiKey: process.env["OPENAI_API_KEY"],
});

const result = await client.completions.create({ model: "string", prompt: "string", best_of: 1, echo: false, frequency_penalty: 0, logit_bias: { key: 1 }, logprobs: null, max_tokens: 16, n: 1, presence_penalty: 0, seed: 1, stop: "string", stream: false, stream_options: { include_usage: true, include_obfuscation: true }, suffix: null, temperature: 1, top_p: 1, user: "string" });
console.log(result);
